  1	function sum(X_val : array<int>, X_crd : array<nat>,
  2	             v_val : array<int>, v_crd : array<nat>, kX : nat, kV : nat, pX_end : nat, pV_end : nat) : (s : int) 
  3	  reads X_val, X_crd
  4	  requires X_val.Length == X_crd.Length
  5	  requires pX_end <= X_crd.Length
  6	  requires 0 <= kX <= X_crd.Length
  7	
  8	  reads v_crd, v_val
  9	  requires v_val.Length == v_crd.Length
 10	  requires pV_end <= v_crd.Length
 11	  requires 0 <= kV <= v_crd.Length
 12	
 13	  decreases pX_end + pV_end - (kX + kV)
 14	  {
 15	    if pV_end <= kV || pX_end <= kX then 
 16	      0
 17	    else if X_crd[kX] == v_crd[kV] then 
 18	      sum(X_val, X_crd, v_val, v_crd, kX + 1, kV + 1, pX_end, pV_end) + v_val[kV] * X_val[kX]
 19	    else if X_crd[kX] < v_crd[kV] then 
 20	      sum(X_val, X_crd, v_val, v_crd, kX + 1, kV, pX_end, pV_end)
 21	    else sum(X_val, X_crd, v_val, v_crd, kX, kV + 1, pX_end, pV_end)
 22	  }
 23	
 24	function min(x : nat, y : nat) : nat {
 25	  if x <= y then x else y
 26	}
 27	
 28	predicate notin(y: nat, x : array<nat>) 
 29	  reads x
 30	{
 31	  forall i :: 0 <= i < x.Length ==> y != x[i]
 32	}
 33	
 34	predicate notin_seq(y: nat, x : seq<nat>) 
 35	{
 36	  forall i :: 0 <= i < |x| ==> y != x[i]
 37	}
 38	
 39	function index_seq(x : nat, y: seq<nat>) : (i : nat)
 40	  ensures i >= |y| ==> notin_seq(x, y)
 41	  ensures i <  |y| ==> y[i] == x
 42	{
 43	  if |y| == 0 then 0 
 44	  else 
 45	    if y[0] == x then 0 
 46	    else 1 + index_seq(x, y[1..])
 47	}
 48	
 49	function index(x : nat, y: array<nat>) : (i : nat)
 50	  reads y
 51	  ensures i >= y.Length ==> notin(x, y)
 52	  ensures i <  y.Length ==> y[i] == x
 53	{
 54	  index_seq(x, y[.. ])
 55	}
