 57	method DSpMSpV(X_val : array<int>, X_crd : array<nat>, X_pos : array<nat>,
 58	                                  X_crd1 : array<nat>, X_len: nat,
 59	              v_val : array<int>, v_crd : array<nat>) returns (y : array<int>)
 60	  // X requirements 
 61	  requires X_pos.Length >= 1
 62	  requires X_val.Length == X_crd.Length
 63	  requires forall i, j :: 0 <= i < j < X_pos.Length ==> X_pos[i] <= X_pos[j];
 64	  requires forall i :: 0 <= i < X_pos.Length ==> 0 <= X_pos[i] <= X_val.Length
 65	
 66	  requires X_len >= X_crd1.Length
 67	  requires forall i :: 0 <= i < X_crd1.Length ==> X_crd1[i] < X_len
 68	
 69	  requires X_crd1.Length < X_pos.Length
 70	  requires forall i, j :: 0 <= i < j < X_crd1.Length ==> X_crd1[i] < X_crd1[j]
 71	
 72	  // v requirements 
 73	  requires v_val.Length == v_crd.Length
 74	
 75	  ensures y.Length == X_len
 76	  ensures forall i :: 0 <= i < y.Length ==> 
 77	    y[i] == 
 78	      if index(i, X_crd1) < X_crd1.Length then 
 79	        sum(X_val, X_crd, v_val, v_crd, X_pos[index(i, X_crd1)], 0, X_pos[index(i, X_crd1)+1], v_val.Length)
 80	      else 0
 81	  {
 82	    var N : nat := X_len;
 83	    y := new int[N](i => 0);
 84	
 85	    var n : nat := 0;
 86	    var kX , pX_end : nat;
 87	    var kV : nat;
 88	    var pV_end : nat := v_val.Length;
 89	    var kX0, kV0    : nat;
 90	    var k : nat;
 91	    var pX_end1 := X_crd1.Length;
 92	    
 93	
 94	    while n < pX_end1
 95	      invariant n <= X_crd1.Length
 96	      invariant forall i :: 0 <= i < n ==> y[X_crd1[i]] == sum(X_val, X_crd, v_val, v_crd, X_pos[i], 0, X_pos[i+1], pV_end)
 97	      invariant forall i :: n <= i < X_crd1.Length ==> y[X_crd1[i]] == 0
 98	      invariant forall i :: 0 <= i < y.Length ==> notin(i, X_crd1) ==> y[i] == 0
 99	      {
100	        kX     := X_pos[n];
101	        pX_end := X_pos[n + 1];
102	        kV     := 0;
103	
104	        while (kX < pX_end && kV < pV_end) 
105	          invariant X_pos[n] <= kX <= pX_end
106	          invariant 0 <= kV <= pV_end
107	          invariant forall i :: n < i < X_crd1.Length ==> y[X_crd1[i]] == 0
108	          invariant forall i :: 0 <= i < y.Length ==> notin(i, X_crd1) ==> y[i] == 0
109	          invariant forall i :: 0 <= i < (n) - 1 ==> y[X_crd1[i]] ==  sum(X_val, X_crd, v_val, v_crd, X_pos[i], 0, X_pos[i+1], pV_end)
110	          invariant y[X_crd1[n]] + sum(X_val, X_crd, v_val, v_crd, kX, kV, pX_end, pV_end) ==  sum(X_val, X_crd, v_val, v_crd, X_pos[n], 0, X_pos[n+1], pV_end)
111	          decreases pX_end + pV_end - (kX + kV)
112	          {
113	            kX0 := X_crd[kX];
114	            kV0 := v_crd[kV];
115	            k := min(kV0, kX0);
116	            if (kX0 == k && kV0 == k) {
117	              y[X_crd1[n]] := y[X_crd1[n]] + X_val[kX] * v_val[kV];
118	              kX := kX + 1;
119	              kV := kV + 1;
120	            } else if (kX0 == k) {
121	              kX := kX + 1;
122	            } else if (kV0 == k) {
123	              kV := kV + 1;
124	            }
125	          }
126	        n := n + 1;
127	      }
128	  }
129	
130	method Main() {
131	  var X_val := new int[4](i => 1);
132	  var X_crd := new nat[4](i => if i <= 3 then (3 - i) * 2 else 0);
133	  var X_pos := new nat[5](i => i);
134	  var X_crd1 := new nat[4](i => i * 2);
135	  var X_pos1 := new nat[2](i => i * 8);
136	  var X_len := 8;
137	
138	  var v_val := new int[4](i => 30 + i);
139	  var v_crd := new nat[4](i => i * 2);
140	  var v_pos := new nat[2](i => if i == 0 then 0 else 4);
141	
142	  var y := DSpMSpV(
143	    X_val,
144	    X_crd,
145	    X_pos,
146	    X_crd1,
147	    X_len,
148	    v_val,
149	    v_crd
150	  );
151	
152	  var i := 0;
153	  while i < 8 { print y[i]; print "; "; i := i + 1; }
154	}
